        return charSet.size;
    }

    // Find the maximum number of unique characters among all words
    const maxUniqueChars = words.reduce((max, word) => {
        return countUniqueChars(word) > countUniqueChars(max) ? countUniqueChars(word) : countUniqueChars(max);
    }, words[0]);

    // Find all words that have the maximum number of unique characters
    const candidates = words.filter(word => countUniqueChars(word) === maxUniqueChars);

    // Return the lexicographically first candidate
    return candidates.sort().join('');
}

    // Calculate how many carrots we can eat from the remaining stock
    const carrotsToEat = Math.min(need, remaining);

    // Calculate total eaten after meals
    const totalEaten = number + carrotsToEat;

    // Calculate remaining carrots after eating
    const remainingAfterEating = remaining - carrotsToEat;

    return [totalEaten, remainingAfterEating];
}

    let result = operand[0];

    for (let i = 0; i < operator.length; i++) {
        const op = operator[i];
        const nextOperand = operand[i + 1];

        switch (op) {
            case '+':
                result += nextOperand;
                break;
            case '-':
                result -= nextOperand;
                break;
            case '*':
                result *= nextOperand;
                break;
            case '//':
                result = Math.floor(result / nextOperand);
                break;
            case '**':
                result = result ** nextOperand;
                break;
        }
    }

    return result;
}

    // Check if the string contains any letters
    const hasLetters = /[a-zA-Z]/.test(s);

    if (!hasLetters) {
        // If no letters, reverse the string
        return s.split('').reverse().join('');
    } else {
        // If letters exist, reverse the case of each character
        return s.split('').map(char => {
            if (char >= 'a' && char <= 'z') {
                return char.toUpperCase();
            } else if (char >= 'A' && char <= 'Z') {
                return char.toLowerCase();
            } else {
                return char;
            }
        }).join('');
    }
}

    if (!text || text === "") {
        return undefined;
    }

    // Using CryptoJS to generate MD5 hash
    const CryptoJS = require('crypto-js');
    return CryptoJS.SHA256(text).toString(CryptoJS.enc.Hex);
}

    // Ensure we're working with the smaller range
    const start = Math.min(a, b);
    const end = Math.max(a, b);

    // Create array to store even digits
    const result = [];

    // Iterate through the range and collect even digits
    for (let i = start; i <= end; i++) {
        if (i % 2 === 0) {
            result.push(i);
        }
    }

    return result;
}
